<!DOCTYPE html>
<html lang="id">
<head>
<meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1">
<meta name="csrf" content="<?= esc($csrf, 'attr') ?>">
<title>Perangkat • Self Service</title>
<style>
:root{--ink:#243c49;--muted:#71828d;--line:#e5ebee;--green:#22b573}*{box-sizing:border-box}body{margin:0;background:#f6f8fa;color:var(--ink);font:14px 'Segoe UI',sans-serif}button,input,select{font:inherit}button{cursor:pointer}header{background:white;border-bottom:1px solid var(--line)}.head{max-width:1320px;margin:auto;padding:22px 28px;display:flex;align-items:center;justify-content:space-between}.brand{font-size:17px;font-weight:700;display:flex;align-items:center;gap:12px}.logo{background:#239c98;color:white;padding:9px 12px;border-radius:10px}main{max-width:1320px;margin:auto;padding:36px 28px}.intro{display:flex;justify-content:space-between;align-items:end;gap:20px;margin-bottom:26px}h1{font-size:28px;letter-spacing:-.6px;margin:0 0 8px}p{color:var(--muted);margin:0;line-height:1.6}.eyebrow{font-size:11px;letter-spacing:1.5px;color:#28958e;font-weight:700;margin-bottom:10px}.btn{border:1px solid #dbe3e8;background:white;color:var(--ink);border-radius:8px;padding:10px 15px}.btn:hover{background:#edf5f5}.stats{display:flex;gap:10px;flex-wrap:wrap;margin-bottom:24px}.stat{padding:12px 18px;background:white;border:1px solid var(--line);border-radius:9px;color:var(--muted)}.stat b{margin-right:8px;font-size:20px;color:var(--ink)}.bar{display:flex;gap:12px;flex-wrap:wrap;background:white;padding:16px;border:1px solid var(--line);border-radius:12px;margin-bottom:20px}input,select{border:1px solid #dbe3e8;border-radius:8px;padding:11px;background:white;color:var(--ink);max-width:100%}.search{flex:1;min-width:220px}.field{display:flex;flex-direction:column;gap:6px}.field label{font-size:11px;color:var(--muted)}.search input{width:100%}.results{display:flex;justify-content:space-between;color:var(--muted);font-size:12px;margin:20px 0 14px}.grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:22px}.card{background:white;border:1px solid var(--line);border-radius:10px;overflow:hidden;box-shadow:0 3px 8px #263c4905}.top{background:#eaf7f6;border-top:5px solid #77c7c1;padding:24px}.card:nth-child(3n+2) .top{background:#f0eef8;border-color:#b5add4}.card:nth-child(3n) .top{background:#faf7e9;border-color:#ded49a}.site{font-size:18px;margin:0 0 8px;line-height:1.4;overflow-wrap:anywhere}.siteid{font-size:12px;color:var(--muted)}.state{display:flex;align-items:end;justify-content:space-between;margin-top:28px}.version{font-size:21px;overflow-wrap:anywhere}.caption{display:block;font-size:12px;color:var(--muted);margin-top:6px}.switcharea{text-align:right;flex-shrink:0}.sw{display:inline-flex;position:relative;width:44px;height:25px}.sw input{opacity:0;width:0;height:0;position:absolute}.sw i{position:absolute;inset:0;border-radius:20px;background:#aab5bd;cursor:pointer}.sw i:before{content:'';position:absolute;left:3px;top:3px;width:19px;height:19px;background:white;border-radius:50%;transition:transform .18s}.sw input:checked+i{background:var(--green)}.sw input:checked+i:before{transform:translateX(19px)}.sw input:focus-visible+i{outline:3px solid #287cbd;outline-offset:3px}.sw input:disabled+i{opacity:.5;cursor:wait}.body{padding:22px 24px}.metrics{display:grid;grid-template-columns:1fr 2fr;gap:14px;margin:15px 0 20px}.metrics strong{font-size:18px;font-weight:600;overflow-wrap:anywhere}.detail{border-top:1px solid var(--line);padding-top:16px;display:grid;gap:10px;font-size:12px}.detail div{display:flex;justify-content:space-between;gap:12px}.detail span{color:var(--muted)}.serial{overflow-wrap:anywhere;text-align:right;min-width:0}.badge{font-size:10px;background:#fff4d8;color:#846220;padding:3px 6px;border-radius:4px}.empty{grid-column:1/-1;text-align:center;padding:65px 20px;border:1px dashed #cfdae0;border-radius:10px;color:var(--muted)}#message{color:#a43131;margin-bottom:14px}button:disabled{opacity:.5;cursor:wait}@media(max-width:1000px){.grid{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:640px){.grid{grid-template-columns:1fr}.head{padding:18px}main{padding:24px 18px}.intro{align-items:start;flex-direction:column}.bar .field{width:100%}.stats{gap:6px}.stat{padding:10px;font-size:12px}.stat b{font-size:18px}h1{font-size:25px}}
</style></head>
<body>
<header><div class="head"><div class="brand"><span class="logo">S</span>Self Service <span style="font-weight:400;color:#71828d">/ Admin</span></div><button class="btn" id="logout">Keluar</button></div></header>
<main>
<div class="intro"><div><div class="eyebrow">MANAJEMEN PERANGKAT</div><h1>Dashboard perangkat</h1><p>Pantau perangkat dan kelola akses setiap site dalam satu tempat.</p></div><button class="btn" id="reload">↻ Muat ulang</button></div>
<div class="stats"><div class="stat"><b id="s-all">—</b>Total terdaftar</div><div class="stat"><b id="s-on">—</b>Aktif</div><div class="stat"><b id="s-off">—</b>Nonaktif</div></div>
<div class="bar"><div class="field search"><label for="q">Pencarian</label><input id="q" placeholder="Cari serial, site ID, atau nama site…" type="search"></div><div class="field"><label for="site">Site ID</label><select id="site"><option value="">Semua site</option></select></div><div class="field"><label for="f">Status perangkat</label><select id="f"><option value="all">Semua status</option><option value="on">Aktif</option><option value="off">Nonaktif</option></select></div><div class="field"><label for="sort">Urutkan site ID</label><select id="sort"><option value="asc">Terkecil → terbesar</option><option value="desc">Terbesar → terkecil</option></select></div></div>
<div id="message" role="alert"></div><div class="results"><span id="count" aria-live="polite">Memuat perangkat…</span><span id="updated"></span></div><div class="grid" id="rows"><div class="empty">Memuat perangkat…</div></div>
</main>
<script>
const csrf = document.querySelector('meta[name=csrf]').content;
// Keep requests on the origin and subfolder used to open this dashboard.
const adminPath = location.pathname.replace(/\/+$/, '');
const endpoint = suffix => adminPath + '/' + suffix;
const $ = s => document.querySelector(s);
const esc = s => String(s ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt = t => { if (!t) return '—'; const d = new Date(t.replace(' ', 'T') + (/Z$|[+-]\d{2}:?\d{2}$/.test(t) ? '' : 'Z')); return isNaN(d) ? '—' : d.toLocaleString('id-ID'); };
const compareSite = (a,b) => {const x=String(a.site_id??''), y=String(b.site_id??'');if(!x||!y)return x? -1:y?1:0;return x.localeCompare(y,'id',{numeric:true}) * ($('#sort').value==='desc'?-1:1);};
let devices = [], loading = false, mutations = 0;
async function request(url,options) {const r=await fetch(url,options);if(r.status===401){location.reload();throw new Error('Sesi berakhir. Silakan masuk kembali.');}if(!r.ok)throw new Error('Permintaan gagal ('+r.status+'). Silakan coba lagi.');return r.json();}
async function load(){if(loading||mutations)return;loading=true;$('#reload').disabled=true;try{const data=await request(endpoint('devices'));if(!Array.isArray(data))throw new Error('Format data perangkat tidak valid.');devices=data;const selected=$('#site').value;const sites=[...new Set(devices.map(d=>String(d.site_id??'')).filter(Boolean))].sort((a,b)=>a.localeCompare(b,'id',{numeric:true}));$('#site').innerHTML='<option value="">Semua site</option>'+sites.map(s=>`<option value="${esc(s)}">${esc(s)}</option>`).join('');$('#site').value=sites.includes(selected)?selected:'';render();$('#updated').textContent='Diperbarui '+new Date().toLocaleTimeString('id-ID');$('#message').textContent='';}catch(e){$('#message').textContent=e.message;if(!devices.length){$('#rows').innerHTML='<div class="empty">Data belum dapat dimuat. Klik Muat ulang untuk mencoba kembali.</div>';$('#count').textContent='Data belum tersedia';}}finally{loading=false;$('#reload').disabled=false;}}
function render(){const q=$('#q').value.trim().toLowerCase(),f=$('#f').value,site=$('#site').value;const list=devices.filter(d=>(f==='all'||(f==='on')===d.is_enable)&&(!site||String(d.site_id??'')===site)&&[d.serial_hardware,d.site_id,d.site_name].join(' ').toLowerCase().includes(q)).sort((a,b)=>compareSite(a,b)||String(a.serial_hardware).localeCompare(String(b.serial_hardware),'id',{numeric:true}));$('#s-all').textContent=devices.length;$('#s-on').textContent=devices.filter(d=>d.is_enable).length;$('#s-off').textContent=devices.filter(d=>!d.is_enable).length;$('#count').textContent=`Menampilkan ${list.length} dari ${devices.length} perangkat`;$('#rows').innerHTML=list.length?list.map(d=>`<article class="card"><div class="top"><h2 class="site">${esc(d.site_name)||'Site belum tersedia'}</h2><span class="siteid">SITE ID · ${esc(d.site_id)||'—'}</span><div class="state"><div><div class="version">${esc(d.version_hardware)||'—'}</div><span class="caption">Versi perangkat</span></div><div class="switcharea"><label class="sw"><input type="checkbox" aria-label="Aktifkan perangkat ${esc(d.serial_hardware)}" data-s="${esc(d.serial_hardware)}" ${d.is_enable?'checked':''} ${mutations?'disabled':''}><i></i></label><span class="caption">${d.is_enable?'Aktif':'Nonaktif'}</span></div></div></div><div class="body"><p>Informasi perangkat ${d.confirmed?'':'<span class="badge">Baru</span>'}</p><div class="metrics"><div><strong>${esc(d.pump_count)}</strong><span class="caption">Pump</span></div><div><strong>${esc(d.device_os)||'—'}</strong><span class="caption">Sistem operasi</span></div></div><div class="detail"><div><span>Serial</span><b class="serial">${esc(d.serial_hardware)}</b></div><div><span>Update terakhir</span><time>${esc(fmt(d.last_update))}</time></div><div><span>Terdaftar</span><time>${esc(fmt(d.registered_at))}</time></div></div></div></article>`).join(''):'<div class="empty">Tidak ada perangkat yang sesuai dengan filter.</div>';}
$('#rows').addEventListener('change',async e=>{const cb=e.target;if(!cb.matches('input[data-s]'))return;const serial=cb.dataset.s,want=cb.checked;if(loading||mutations){cb.checked=!want;return;}if(!want&&!confirm('Nonaktifkan '+serial+'? Alat ini akan ditolak saat request berikutnya.')){cb.checked=true;return;}mutations++;document.querySelectorAll('[data-s]').forEach(el=>el.disabled=true);try{await request(endpoint('devices/toggle'),{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-Token':csrf},body:JSON.stringify({serial_hardware:serial,is_enable:want})});devices.find(d=>d.serial_hardware===serial).is_enable=want;$('#message').textContent='';}catch(e){$('#message').textContent=e.message;}finally{mutations--;render();}});
$('#q').addEventListener('input',render);['#f','#site','#sort'].forEach(s=>$(s).addEventListener('change',render));$('#reload').addEventListener('click',load);$('#logout').addEventListener('click',async()=>{$('#logout').disabled=true;try{await request(endpoint('logout'),{method:'POST',headers:{'X-CSRF-Token':csrf}});location.reload();}catch(e){$('#message').textContent=e.message;$('#logout').disabled=false;}});load();setInterval(load,30000);
</script></body></html>
